UPDATE programmes SET image_url=CASE slug WHEN 'north-star' THEN 'https://www.gitexcac.com/contents/Theme-2025/images/GACASIAthumb0502.jpg' WHEN 'investor-programme' THEN 'https://www.gitexcac.com/images/MAX01827-img.jpg' ELSE 'https://www.gitexcac.com/images/Ai-council-Meeting.jpg' END;
