UPDATE sponsor_logos SET image_url=CASE name WHEN 'Huawei' THEN 'https://www.gitexcac.com/images/HW_POS_RGB.png' WHEN 'Presight' THEN 'https://www.gitexcac.com/images/PresightMaster.png' WHEN 'Lenovo' THEN 'https://www.gitexcac.com/images/LenovoLogo-POS-Red.png' ELSE 'https://www.gitexcac.com/images/H3C-up.png' END;
